/* IMS frontend-stall watchdog: proves the browser -> Grafana -> Postgres
   query pipeline is still alive on every dashboard refresh cycle. If this
   panel goes STALE_MS without being re-invoked, the dashboard's own
   refresh timer has stalled (the "data stops retrieving, requires F5"
   symptom) -- force a full page reload, automating what an operator would
   otherwise do by hand. Safe to prepend to any getOption body: wrapped in
   its own IIFE, touches only window.__imsWatchdog*, never collides with
   panel-local variable names. */
(function (staleMs) {
  if (!window.__imsWatchdog) {
    window.__imsWatchdogTick = Date.now();
    window.__imsWatchdog = setInterval(function () {
      if (Date.now() - window.__imsWatchdogTick > staleMs) {
        window.location.reload();
      }
    }, Math.min(staleMs / 4, 30000));
  }
  window.__imsWatchdogTick = Date.now();
})(240000);

const frame = context.panel.data.series[0];
const timeField = frame && frame.fields.find((f) => f.type === 'time');
const serverTime = timeField ? (timeField.values.buffer || timeField.values)[0] : Date.now();

const d = new Date(serverTime);
const hh = String(d.getUTCHours()).padStart(2, '0');
const mm = String(d.getUTCMinutes()).padStart(2, '0');
const ss = String(d.getUTCSeconds()).padStart(2, '0');

return {
  backgroundColor: 'transparent',
};

targets.rawSql:
/* RESOLVED 2026-08-10 (migration 064): v_machine_spc_fleet is now a materialized view refreshed every 60s via a TimescaleDB background job, not recomputed per read. Previously QUERY_BUDGET_EXEMPT (~150ms); now sub-millisecond. */
SELECT eqp_id AS "Machine", ROUND(worst_cpk::NUMERIC, 2) AS "Worst Cpk"
FROM public.v_machine_spc_fleet
WHERE worst_cpk IS NOT NULL
ORDER BY worst_cpk ASC
LIMIT 1;

/* NO_TIMEFILTER_INTENTIONAL: full dataset scope */
SELECT COUNT(*)::NUMERIC AS value
FROM public.ldi_alarm_log a
JOIN public.ldi_alarm_ms_code m ON a.errorcode::TEXT = m.alarm_code::TEXT
WHERE a.equipmentid IN (${machine_id:sqlstring}) AND m.severity IN ('Critical', 'Major');
